const crypto = require('crypto');
const secret = $env.HQ_SIGNING_SECRET || '';
const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const header = String(item.json.headers['x-hq-signature'] || '');
const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
const t = parseInt(parts.t, 10);
const now = Math.floor(Date.now() / 1000);
const want = crypto.createHmac('sha256', secret).update(`${t}.`).update(raw).digest('hex');
const got = String(parts.v1 || '');
if (!secret || !t || Math.abs(now - t) > 300 || want.length !== got.length || !crypto.timingSafeEqual(Buffer.from(want), Buffer.from(got))) {
  throw new Error('the hub signature is missing, old or wrong');
}
const req = JSON.parse(raw.toString('utf8'));
// --- the rule work goes here (fetch, format, file); this demo only echoes ---
const body = JSON.stringify({
  token: req.token,
  ok: true,
  text: `n8n demo: step ${req.step} of run ${req.run}`,
  data: { echoed_inputs: Object.keys(req.inputs || {}) },
});
const ts = Math.floor(Date.now() / 1000);
const mac = crypto.createHmac('sha256', secret).update(`${ts}.`).update(body).digest('hex');
return [{ json: { body, signature: `t=${ts},v1=${mac}` } }];
